WITH MathLetterGradedStats AS ( SELECT d.DEPARTMENT_NAME, c.GRADE_TYPE, COUNT(c.SUBJECT_ID) AS subject_count, MIN(c.TOTAL_UNITS) AS min_total_units FROM SIS_DEPARTMENT d JOIN COURSE_CATALOG_SUBJECT_OFFERED c ON d.DEPARTMENT_CODE = c.DEPARTMENT_CODE WHERE c.IS_OFFERED_THIS_YEAR = 'Y' AND c.GRADE_TYPE = 'L' AND d.DEPARTMENT_NAME = 'Mathematics' AND d.DEPARTMENT_CODE = '18' GROUP BY d.DEPARTMENT_NAME, c.GRADE_TYPE ), TopDepartments2022 AS ( SELECT SIS_DEPARTMENT.DEPARTMENT_NAME, COUNT(COURSE_CATALOG_SUBJECT_OFFERED.SUBJECT_ID) AS subject_count FROM SIS_DEPARTMENT JOIN COURSE_CATALOG_SUBJECT_OFFERED ON SIS_DEPARTMENT.DEPARTMENT_CODE = COURSE_CATALOG_SUBJECT_OFFERED.DEPARTMENT_CODE WHERE COURSE_CATALOG_SUBJECT_OFFERED.ACADEMIC_YEAR = 2022 AND SIS_DEPARTMENT.IS_DEGREE_GRANTING = 'Y' AND SIS_DEPARTMENT.DEPARTMENT_CODE <> '17' GROUP BY SIS_DEPARTMENT.DEPARTMENT_NAME ORDER BY subject_count DESC LIMIT 10 ) SELECT m.DEPARTMENT_NAME, m.GRADE_TYPE, m.subject_count AS math_letter_subject_count, m.min_total_units, t.subject_count AS top_dept_2022_subject_count FROM MathLetterGradedStats m LEFT JOIN TopDepartments2022 t ON m.DEPARTMENT_NAME = t.DEPARTMENT_NAME ORDER BY m.DEPARTMENT_NAME, m.GRADE_TYPE;